frappe.ui.form.on('Supplier', {
    refresh(frm) {
        if (frm.is_new()) return;
        frappe.call({
            method: 'frappe.client.get_list',
            args: {
                doctype: 'Company',
                filters: {'default_supplier': frm.doc.name},
                fields: ['name'],
                limit_page_length: 1
            },
            callback: function(r) {
                if (r.message && r.message.length) {
                    const c = r.message[0].name;
                    if (frm.doc.represents_company !== c) {
                        frm.set_value('represents_company', c);
                    }
                    frm.set_df_property('represents_company', 'read_only', 1);
                    frm.set_df_property('represents_company', 'description', 'Auto-set: this Supplier is the Default Supplier for Company "' + c + '". Cannot be changed.');
                }
            }
        });
    }
});

frappe.ui.form.on('Vehicle', {
    refresh: function(frm) {
        toggle_vendor(frm);
    },
    custom_market: function(frm) {
        toggle_vendor(frm);
    }
});

function toggle_vendor(frm) {
    if (frm.doc.custom_market) {
        // Enable Vendor
        frm.set_df_property('custom_vendor', 'read_only', 0);
    } else {
        // Disable + clear Vendor (only if it actually has a value — avoid
        // dirtying the form on every refresh when it's already empty)
        frm.set_df_property('custom_vendor', 'read_only', 1);
        if (frm.doc.custom_vendor) {
            frm.set_value('custom_vendor', null);
        }
    }
}

frappe.ui.form.on('Trip', {
    refresh: function(frm) {
        // Replace 'arrival_unloading_point_date_time' with your actual field name
        frm.set_df_property('arrival_unloading_point_date_time', 'options', {
            format: 'YYYY-MM-DD HH:mm',
            timepicker_options: {
                showSeconds: false,
                timeFormat: 'HH:mm'
            }
        });
        
        // Repeat for other fields like Reach Loading Point, Dispatch, etc.
        frm.set_df_property('reach_loading_point_date_time', 'options', {
            timepicker_options: { showSeconds: false }
        });
    }
});

frappe.ui.form.on('Trip', {

    business_format: function(frm) {
        frm.set_value('customer', '');

        if (frm.doc.business_format) {
            frappe.db.get_value(
                'Business Format',
                frm.doc.business_format,
                'customer_group',
                function(data) {
                    if (data && data.customer_group) {
                        frm.set_query('customer', function() {
                            return {
                                filters: {
                                    customer_group: data.customer_group
                                    // ❌ Removed: status: 'Enabled'
                                }
                            };
                        });
                        frm.refresh_field('customer');
                    } else {
                        frm.set_query('customer', function() {
                            return {};
                        });
                    }
                }
            );
        } else {
            frm.set_query('customer', function() {
                return {};
            });
        }
    },

    onload: function(frm) {
        if (frm.doc.business_format) {
            frappe.db.get_value(
                'Business Format',
                frm.doc.business_format,
                'customer_group',
                function(data) {
                    if (data && data.customer_group) {
                        frm.set_query('customer', function() {
                            return {
                                filters: {
                                    customer_group: data.customer_group
                                }
                            };
                        });
                    }
                }
            );
        }
    }
});

