function add_copy_button_near_field(frm) {
    // Avoid duplicate buttons on re-render
    if (frm.$wrapper.find('.copy-preview-btn').length) return;

    let field = frm.get_field('email_preview');
    if (!field || !field.$wrapper) return;

    // Inject button just above the email_preview textarea
    let btn_html = `
        <div style="display: flex; justify-content: flex-end; margin-bottom: 4px;">
            <button class="btn btn-xs btn-default copy-preview-btn"
                    style="display: flex; align-items: center; gap: 4px; 
                           padding: 4px 10px; font-size: 12px; cursor: pointer;">
                <svg xmlns="http://www.w3.org/2000/svg" width="13" height="13" 
                     viewBox="0 0 24 24" fill="none" stroke="currentColor" 
                     stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                    <rect x="9" y="9" width="13" height="13" rx="2" ry="2"></rect>
                    <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"></path>
                </svg>
                Copy Preview
            </button>
        </div>
    `;

    // Prepend above the field label+input area
    field.$wrapper.prepend(btn_html);

    // Bind click event
    frm.$wrapper.find('.copy-preview-btn').on('click', function() {
        // Read directly from DOM textarea (works for unsaved docs too)
        let textarea = field.$wrapper.find('textarea')[0];
        let preview_text = textarea ? textarea.value : frm.doc.email_preview;

        if (!preview_text) {
            frappe.msgprint(__('No email preview content to copy.'));
            return;
        }

        // Clipboard copy with HTTP fallback
        let temp = document.createElement('textarea');
        temp.value = preview_text;
        temp.style.cssText = 'position:fixed;top:0;left:0;opacity:0;';
        document.body.appendChild(temp);
        temp.focus();
        temp.select();

        try {
            document.execCommand('copy');
            // Change button text temporarily to confirm
            let btn = frm.$wrapper.find('.copy-preview-btn');
            btn.html(`
                <svg xmlns="http://www.w3.org/2000/svg" width="13" height="13" 
                     viewBox="0 0 24 24" fill="none" stroke="green" 
                     stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
                    <polyline points="20 6 9 17 4 12"></polyline>
                </svg>
                Copied!
            `).css('color', 'green');

            setTimeout(() => {
                btn.html(`
                    <svg xmlns="http://www.w3.org/2000/svg" width="13" height="13" 
                         viewBox="0 0 24 24" fill="none" stroke="currentColor" 
                         stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                        <rect x="9" y="9" width="13" height="13" rx="2" ry="2"></rect>
                        <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"></path>
                    </svg>
                    Copy Preview
                `).css('color', '');
            }, 2000);

        } catch (err) {
            frappe.msgprint(__('Copy failed. Please select and copy manually.'));
        }

        document.body.removeChild(temp);
    });
}

function update_email_preview(frm) {
    if (!frm.doc.email_template) return;

    frappe.call({
        method: 'logicore.logicore.doctype.trip_primary.trip_primary.get_rendered_email_template',
        args: {
            doc: frm.doc,
            template_name: frm.doc.email_template
        },
        callback: function(r) {
            if (r.message) {
                frm.set_value('email_preview', r.message);
                frm.refresh_field('email_preview');
            }
        },
        error: function(r) {
            frm.set_value('email_preview', 'Error loading preview.');
        }
    });
}

