frappe.ui.form.on("Trip Primary", {
    refresh(frm) {
        frm.add_custom_button(__('Copy Email Template'), function () {
            frm.trigger("show_email_dialog");
        }).addClass("btn-primary");
    },

    show_email_dialog(frm) {
        // Basic validation - TCN No check
        if (!frm.doc.tcano && !frm.doc.tcn_no) {
            frappe.msgprint(__('Please enter TCN No first.'));
            return;
        }

        let d = new frappe.ui.Dialog({
            title: __('Email Template Preview'),
            fields: [
                {
                    label: __('Select Template'),
                    fieldname: 'email_template',
                    fieldtype: 'Link',
                    options: 'Email Template',
                    default: frm.doc.email_template || '',
                    reqd: 1,
                    on_change: function () {
                        let selected_template = d.get_value('email_template');
                        if (selected_template) {
                            frappe.call({
                                method: "logicore.logicore.doctype.trip_primary.trip_primary.get_rendered_email_template",
                                args: {
                                    doc: frm.doc,
                                    template_name: selected_template
                                },
                                callback(r) {
                                    if (r.message) {
                                        d.set_value('preview_area', r.message);
                                    }
                                },
                                error() {
                                    d.set_value('preview_area', 'Error loading preview.');
                                }
                            });
                        } else {
                            d.set_value('preview_area', '');
                        }
                    }
                },
                {
                    fieldtype: 'Section Break'
                },
                {
                    label: __('Email Content Preview'),
                    fieldname: 'preview_area',
                    fieldtype: 'Small Text',
                    read_only: 0
                }
            ],
            primary_action_label: __('Copy Preview'),
            primary_action(values) {
                let content = d.get_value('preview_area');
                if (content) {
                    _copy_to_clipboard(content);
                    frappe.show_alert({
                        message: __('Content copied to clipboard!'),
                        indicator: 'green'
                    }, 4);
                    d.hide();
                } else {
                    frappe.msgprint(__('Nothing to copy! Please select a template first.'));
                }
            },
            secondary_action_label: __('Close'),
            secondary_action() {
                d.hide();
            }
        });

        // Style the dialog after render
        setTimeout(() => {
            d.$wrapper.find('[data-fieldname="preview_area"] textarea').css({
                'min-height': '280px',
                'font-family': 'monospace',
                'font-size': '12.5px',
                'background-color': '#f8fbff',
                'color': '#2c3e50',
                'border': '1.5px solid #c5def0',
                'border-radius': '6px'
            });
            d.$wrapper.find('.modal-dialog').css('max-width', '680px');
        }, 100);

        // Auto-load preview if template already set on the form
        if (frm.doc.email_template) {
            d.set_value('email_template', frm.doc.email_template);
            frappe.call({
                method: "logicore.logicore.doctype.trip_primary.trip_primary.get_rendered_email_template",
                args: {
                    doc: frm.doc,
                    template_name: frm.doc.email_template
                },
                callback(r) {
                    if (r.message) {
                        d.set_value('preview_area', r.message);
                    }
                }
            });
        }

        d.show();
    }
});

// Clipboard Helper
function _copy_to_clipboard(text) {
    if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).catch(() => _copy_via_textarea(text));
    } else {
        _copy_via_textarea(text);
    }
}

function _copy_via_textarea(text) {
    const ta = document.createElement("textarea");
    ta.value = text;
    ta.style.position = "fixed";
    ta.style.opacity = "0";
    document.body.appendChild(ta);
    ta.select();
    try {
        document.execCommand("copy");
    } catch (err) {
        frappe.msgprint(__('Unable to copy automatically. Please copy manually.'));
        console.error('Unable to copy', err);
    }
    document.body.removeChild(ta);
}

frappe.ui.form.on('Address', {

    custom_cityname: function(frm) {
        if (!frm.doc.custom_cityname) {
            frappe.model.set_value(frm.doctype, frm.docname, 'city',  '');
            frappe.model.set_value(frm.doctype, frm.docname, 'state', '');
            return;
        }
        frappe.db.get_doc('City', frm.doc.custom_cityname)
            .then(function(d) {
                frappe.model.set_value(frm.doctype, frm.docname, 'city',    d.name1 || d.name || '');
                frappe.model.set_value(frm.doctype, frm.docname, 'state',   d.state   || '');
                frappe.model.set_value(frm.doctype, frm.docname, 'country', d.country || 'India');
            })
            .catch(function(e) { console.error('City fetch error', e); });
    }
});
